def apply(asset):
    """✍ Writes the root corrections into the asset (the rig and the 2D geometry are written by the kit and the draw script)."""
    for anchor in asset["anchors"]:
        if anchor["id"] == "exhaust-top":
            anchor["x"], anchor["y"] = 2.0, 0
    for emitter in asset["thermal"]["emitters"]:
        if emitter["id"] == "exhaust-air":
            emitter["directionDeg"] = 0
    known = {r["id"] for r in asset["provenance"]["references"]}
    asset["provenance"]["references"] += [r for r in REFERENCES if r["id"] not in known]
    asset["provenance"]["notes"] = NOTES
    asset["structure"]["assumptions"][0] = STRUCTURE
    asset["thermal"]["assumptions"][1] = EMITTER
    for region in asset["thermal"]["regions"]:
        if region["id"] == "feet":
            region["areaM2"] = 0.072
    for scale, texts in DECISIONS.items():
        asset["representations"][scale]["decisions"] = texts
